{
  "root_causes": [
    {
      "service": "ts-user-service",
      "fault_kind": "network_loss",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT src, count(*) n_calls, sum(CASE WHEN gap>100 THEN 1 ELSE 0 END) calls_gap_over_100ms, round(max(gap),1) max_gap_ms FROM (SELECT 'abn' src, CAST(c.duration AS BIGINT)/1e6 - CAST(s.duration AS BIGINT)/1e6 gap FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='ts-user-service' AND c.attr_span_kind='Client' AND c.span_name='POST' AND s.service_name='ts-auth-service' AND s.attr_span_kind='Server' UNION ALL SELECT 'norm', CAST(c.duration AS BIGINT)/1e6 - CAST(s.duration AS BIGINT)/1e6 FROM normal_traces c JOIN normal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='ts-user-service' AND c.attr_span_kind='Client' AND c.span_name='POST' AND s.service_name='ts-auth-service' AND s.attr_span_kind='Server') GROUP BY src",
          "claim": "ts-user-service→ts-auth-service POST calls: 3 of 15 abnormal calls gained 200–645ms outside the auth server span; normal max gap 1.3ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT CAST(c.duration AS BIGINT)/1e6 client_ms, CAST(s.duration AS BIGINT)/1e6 auth_server_ms, (CAST(c.duration AS BIGINT)-CAST(s.duration AS BIGINT))/1e6 gap_ms FROM abnormal_traces c JOIN abnormal_traces s ON s.parent_span_id=c.span_id WHERE c.service_name='ts-user-service' AND c.attr_span_kind='Client' AND c.span_name='POST' AND s.service_name='ts-auth-service' AND s.attr_span_kind='Server' AND (CAST(c.duration AS BIGINT)-CAST(s.duration AS BIGINT))>100000000 ORDER BY gap_ms DESC",
          "claim": "Slow calls to auth take 705ms and 720ms client-side while auth's own server span is about 75ms; the gap is in transit."
        },
        {
